def main():
    wb = Workbook()
    ws = wb.active
    ws.title = "Чек-лист"
    n = len(TASKS)
    last = 3 + n
    ws["A1"] = "Чек-лист задач K-truck по итогам анализа"
    ws["A1"].font = Font(bold=True, size=14)
    ws["F1"] = "Готово:"
    ws["G1"] = f'=COUNTIF(H4:H{last},"Готово")&" из "&COUNTA(C4:C{last})'
    ws["A2"] = "Статус меняйте в колонке «Статус». Приоритет 1 — сделать первым. Сроки и ответственные — предложение, поправьте под себя."
    head = ["№", "Блок", "Задача", "Зачем (вывод анализа)", "Приоритет", "Ответственный", "Срок", "Статус", "Как проверить", "Откуда", "Комментарий"]
    ws.append(head)
    for i, (block, task, why, prio, owner, due, check, src) in enumerate(TASKS, 1):
        ws.append([i, block, task, why, prio, owner, due, "Не начато", check, src, ""])
    for c in ws[3]:
        c.font = Font(bold=True)
        c.fill = PatternFill("solid", fgColor="DDEBE4")
    widths = [5, 22, 55, 50, 10, 20, 12, 13, 38, 24, 30]
    for i, w in enumerate(widths):
        ws.column_dimensions[chr(65 + i)].width = w
    for row in ws.iter_rows(min_row=4, max_row=last):
        for c in row:
            c.alignment = Alignment(wrap_text=True, vertical="top")
        row[6].number_format = "DD.MM.YYYY"
    dv = DataValidation(type="list", formula1='"Не начато,В работе,Готово,Отложено"', allow_blank=False)
    ws.add_data_validation(dv)
    dv.add(f"H4:H{last}")
    green = PatternFill("solid", fgColor="D9EAD3")
    yellow = PatternFill("solid", fgColor="FFF2CC")
    ws.conditional_formatting.add(f"H4:H{last}", CellIsRule(operator="equal", formula=['"Готово"'], fill=green))
    ws.conditional_formatting.add(f"H4:H{last}", CellIsRule(operator="equal", formula=['"В работе"'], fill=yellow))
    ws.freeze_panes = "D4"
    ws.auto_filter.ref = f"A3:K{last}"

    s = wb.create_sheet("По блокам")
    s.append(["Блок", "Задач", "Готово", "Приоритет 1", "Прогресс"])
    blocks = []
    for t in TASKS:
        if t[0] not in blocks:
            blocks.append(t[0])
    for r, b in enumerate(blocks, 2):
        rng_b, rng_h, rng_p = f"'Чек-лист'!B4:B{last}", f"'Чек-лист'!H4:H{last}", f"'Чек-лист'!E4:E{last}"
        s.append([b, f'=COUNTIF({rng_b},A{r})', f'=COUNTIFS({rng_b},A{r},{rng_h},"Готово")',
                  f'=COUNTIFS({rng_b},A{r},{rng_p},1)', f"=IF(B{r}=0,0,C{r}/B{r})"])
        s[f"E{r}"].number_format = "0%"
    tr = len(blocks) + 2
    s.append(["Всего", f"=SUM(B2:B{tr - 1})", f"=SUM(C2:C{tr - 1})", f"=SUM(D2:D{tr - 1})", f"=IF(B{tr}=0,0,C{tr}/B{tr})"])
    s[f"E{tr}"].number_format = "0%"
    for c in s[1] + s[tr]:
        c.font = Font(bold=True)
    for col, w in zip("ABCDE", [30, 8, 8, 12, 10]):
        s.column_dimensions[col].width = w

    d = wb.create_sheet("Уже сделано")
    d.append(["Что сделано в проекте", "Где результат"])
    for r in DONE:
        d.append(list(r))
    for c in d[1]:
        c.font = Font(bold=True)
    d.column_dimensions["A"].width = 70
    d.column_dimensions["B"].width = 60

    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    wb.save(OUT)
    print(OUT, n, "задач")


if __name__ == "__main__":
    main()
